import{_ as a,C as e,o as n,c as l,ai as t,E as p}from"./chunks/framework.hSDj3-GX.js";const r="/OS/assets/image-20260611182853911.Ci3BRAzG.png",o="/OS/assets/image-20260611183338078.Cl3NeZpk.png",h="/OS/assets/image-20260611183607878.BK9sI6Vt.png",C=JSON.parse('{"title":"进程间通信 IPC（Inter-Process Communication）","description":"","frontmatter":{},"headers":[],"relativePath":"进程与线程/4_5 进程间通信.md","filePath":"进程与线程/4_5 进程间通信.md","lastUpdated":1781415925000}'),k={name:"进程与线程/4_5 进程间通信.md"};function d(c,s,g,u,m,F){const i=e("QuizSet");return n(),l("div",null,[s[0]||(s[0]=t(`<h1 id="进程间通信-ipc-inter-process-communication" tabindex="-1">进程间通信 IPC（Inter-Process Communication） <a class="header-anchor" href="#进程间通信-ipc-inter-process-communication" aria-label="Permalink to &quot;进程间通信 IPC（Inter-Process Communication）&quot;">​</a></h1><blockquote><p>进程彼此隔离，但有时又需要合作，所以需要支持进程间通信。</p></blockquote><p><strong>方法总览：</strong></p><ul><li>低级通信：只能传递状态和整数值（控制信息），包括进程互斥和同步所采用的信号量和管程机制。缺点： <ul><li>信息量小</li><li>编程复杂</li><li>适用范围受限：低级通信机制往往要求通信双方处于共享地址空间环境</li></ul></li><li>高级通信：主要有三类。 <ul><li>管道</li><li>共享内存</li><li>消息系统</li></ul></li></ul><h2 id="管道-pipe" tabindex="-1">管道（Pipe） <a class="header-anchor" href="#管道-pipe" aria-label="Permalink to &quot;管道（Pipe）&quot;">​</a></h2><p>分为无名管道和有名管道两种。</p><h3 id="无名管道-pipe" tabindex="-1">无名管道 (Pipe) <a class="header-anchor" href="#无名管道-pipe" aria-label="Permalink to &quot;无名管道 (Pipe)&quot;">​</a></h3><blockquote><p>管道是操作系统提供的一个内核缓冲区，用于让一个进程把数据传给另一个进程。</p></blockquote><p><strong>特点：</strong></p><ol><li><strong>半双工：</strong>数据通常单向流动（A 写，B 读）若双向通信，通常建立两个管道。</li><li><strong>亲缘进程使用：</strong>通常用于父子进程、兄弟进程（通过 fork 继承文件描述符）。</li><li><strong>先进先出（FIFO）：</strong>先写入的数据先被读出。</li><li><strong>存在于内存中：</strong>管道不是普通磁盘文件，而是内核中的临时通信通道。</li></ol><p>以下是我们可能会在 bash 中用到的管道操作</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $1}&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$access_src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> uniq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sort</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{print $2, $1}&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $summary_dst</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>下面是一个更能体现管道是两个进程间的通信的例子：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    sleep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>说明：</strong></p><p>Shell 会同时启动两个进程：</p><p>左侧进程：持续输出 hello 右侧进程：head -n 5 读取前 5 行</p><p>左侧进程的输出通过管道传给右侧进程作为输入。 当右侧读满 5 行后退出，管道关闭，左侧进程也结束。</p><h3 id="有名管道-named-pipe-又称fifo" tabindex="-1">有名管道（Named Pipe，又称FIFO） <a class="header-anchor" href="#有名管道-named-pipe-又称fifo" aria-label="Permalink to &quot;有名管道（Named Pipe，又称FIFO）&quot;">​</a></h3><p>无名管道通常用于具有亲缘关系的进程（如父子进程、兄弟进程）。</p><p>为了解决这一限制，操作系统提供了<strong>有名管道</strong>：它在文件系统中拥有一个路径名，不相关的进程只要能够访问该路径，就可以通过它进行通信。</p><p><strong>特点：</strong></p><ol><li><strong>有名字：</strong> 以文件路径形式存在，可通过 <code>mkfifo</code> 创建。</li><li><strong>无亲缘关系也可通信：</strong> 不要求进程之间存在父子关系。</li><li><strong>先进先出（FIFO）：</strong> 先写入的数据先被读出。</li><li><strong>本质仍是管道：</strong> 数据通常在内核缓冲区中流动，而不是长期保存到磁盘。</li></ol><h2 id="消息传递-message-passing" tabindex="-1">消息传递（message passing） <a class="header-anchor" href="#消息传递-message-passing" aria-label="Permalink to &quot;消息传递（message passing）&quot;">​</a></h2><p>使用通信原语：<code>send(destination, &amp;message)</code>、<code>receive(source, &amp;message)</code></p><ul><li>调用方式： <ul><li>阻塞调用</li><li>非阻塞调用</li></ul></li><li>通信方式： <ul><li>通过进程号直接通信</li><li>通过mailbox/消息队列间接通信</li></ul></li><li>数据通常经过内核复制</li></ul><p><img src="`+r+'" alt=""></p><p><img src="'+o+'" alt=""></p><h2 id="共享内存" tabindex="-1">共享内存 <a class="header-anchor" href="#共享内存" aria-label="Permalink to &quot;共享内存&quot;">​</a></h2><p><strong>核心：</strong>将同一块物理内存映射到通信进程双方各自的进程地址空间</p><p><strong>优点：</strong>最有效、最快的IPC形式，避免了开销巨大的缓冲复制</p><p><strong>问题：</strong>共享内存可以同时读，但不能同时写，需要同步机制约束</p><p><img src="'+h+'" alt=""></p><h2 id="复习题" tabindex="-1">复习题 <a class="header-anchor" href="#复习题" aria-label="Permalink to &quot;复习题&quot;">​</a></h2>',34)),p(i,{collection:"final-review"})])}const _=a(k,[["render",d]]);export{C as __pageData,_ as default};
